from Crypto.Util.number import getPrime, bytes_to_long, isPrime
from sage.all import *

p = getPrime(1024)
q = getPrime(1024)
e = 65537
n = p * q

leak = q >> 490

flag = b'my_secret_hehe'
ct = pow(bytes_to_long(flag), e, n)

print("n =", n)
print("ct =", ct)
print("leak =", leak)

